{"implementation": "/-- The maximal runs of equal neighbours in `l`, in order, each as its value and its length; the empty list has no runs. -/
def runLengths (l : List Nat) : List (Nat × Nat) :=
  match l with
  | [] => []
  | x :: rest =>
    let run := rest.takeWhile (· == x)
    (x, run.length + 1) :: runLengths (rest.dropWhile (· == x))", "notes": "Takes the whole run at the head, then goes on with what is left."}
